        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='POST /api/v1/basicservice/basic/travels' GROUP BY ALL", "claim": "Basic-service's own server spans for /basic/travels still return 200 with normal latency, so the callee is healthy."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level='SEVERE' GROUP BY ALL ORDER BY n DESC", "claim": "Travel-service logs throw HttpClientErrorException 408 whose quoted body is a successful, intact payload."},
